 if(!E.validParams(p.params)||!t?.available||t.protocol!==E.PROTOCOL||t.league!==f.match.league||t.season!==f.match.season||t.tuningSeason!==E.previousSeason(f.match.season)||!validDate(t.before)||t.before>p.cutoff||t.before>E.seasonStart(f.match.season)||!validDate(t.validationFrom)||!validDate(t.validationTo)||t.validationFrom>t.validationTo||t.validationTo>=t.before||!Number.isInteger(t.n)||t.n<E.MIN_VALIDATION||t.n>10000||!num(t.brier,0,2)||!num(t.baseBrier,0,2)||t.brier>t.baseBrier+1e-12||!E.validParams(t.params)||t.params.halfLife!==p.params.halfLife||t.params.prior!==p.params.prior||snap.model?.version!==E.VERSION||snap.model?.params?.halfLife!==p.params.halfLife||snap.model?.params?.prior!==p.params.prior||identity(s)!==identity(t))throw Error('Audit du modèle ajusté invalide');
