function probs(p){return `<div class="probbar">${p.probs.map(x=>`<span style="width:${x*100}%"></span>`).join('')}</div><div class="probs"><div>Domicile<b>${pct(p.probs[0])}</b></div><div>Nul<b>${pct(p.probs[1])}</b></div><div>Extérieur<b>${pct(p.probs[2])}</b></div></div>`}
