function chartPanel(rows,{id='trackingEvolution',title='La qualité des prévisions dans le temps',label='Prévisions enregistrées',adjusted=null}={}){
 const points=I.series(rows),other=adjusted?I.series(adjusted):null;
 if(!points.length)return `<div class="panel" id="${id}"><h2>${esc(title)}</h2><p>Le graphique apparaîtra après le premier résultat évaluable d’une prévision enregistrée. Les simulations historiques restent disponibles dans Laboratoire.</p></div>`;
 const width=innerWidth<540?380:620,height=250,left=43,right=14,top=16,bottom=38,plotW=width-left-right,plotH=height-top-bottom;
 const values=points.flatMap(p=>[p.brier,p.reference]).concat(other?.map(p=>p.brier)||[]),low=Math.max(0,Math.floor((Math.min(...values)-.08)*10)/10),high=Math.min(2,Math.ceil((Math.max(...values)+.08)*10)/10);
 const from=M.day(points[0].date),to=M.day(points.at(-1).date),x=d=>left+(to===from?plotW/2:(M.day(d)-from)/(to-from)*plotW),y=v=>top+(high-v)/(high-low)*plotH;
 const line=(list,key,cls)=>`<polyline class="chart-line ${cls}" points="${list.map(p=>x(p.date).toFixed(2)+','+y(p[key]).toFixed(2)).join(' ')}"/>`;
 const ticks=Array.from({length:5},(_,i)=>low+(high-low)*i/4);
 const svg=`<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(title)}. Brier cumulé, plus bas signifie mieux. ${points.at(-1).n} matchs."><title>${esc(title)} · Brier cumulé</title>${ticks.map(v=>`<line class="chart-grid" x1="${left}" y1="${y(v)}" x2="${width-right}" y2="${y(v)}"/><text x="${left-7}" y="${y(v)+4}" text-anchor="end">${v.toFixed(2)}</text>`).join('')}${line(points,'reference','chart-reference')}${line(points,'brier','')}${other?line(other,'brier','chart-adjusted'):''}${points.filter((p,i)=>points.length<25||i===points.length-1).map(p=>`<circle cx="${x(p.date)}" cy="${y(p.brier)}" r="3.5" fill="#587f2d"><title>${esc(date(p.date))} · ${p.n} matchs · Brier ${p.brier.toFixed(4)}</title></circle>`).join('')}<text x="${left}" y="${height-12}">${esc(date(points[0].date))}</text>${to!==from?`<text x="${width-right}" y="${height-12}" text-anchor="end">${esc(date(points.at(-1).date))}</text>`:''}</svg>`;
 return `<div class="panel" id="${id}"><h2>${esc(title)}</h2><p>Brier cumulé après chaque date de match. Une valeur plus basse indique de meilleures probabilités sur les résultats disponibles.</p>${svg}<div class="chart-legend"><span><i></i>${esc(label)}</span><span class="reference"><i></i>Fréquences historiques</span>${other?'<span class="adjusted"><i></i>Ajusté · v2</span>':''}</div><p class="small">${points.at(-1).n} matchs · les premiers points peuvent varier fortement.${other?' Comparaison sur les mêmes matchs.':' Les résultats peuvent évoluer si une source corrige un score ; les probabilités enregistrées restent figées.'}</p><details class="chart-data"><summary>Lire les valeurs (${points.length} dates)</summary><div class="tablewrap"><table><thead><tr><th>Date</th><th class="num">Matchs</th><th class="num">Brier</th><th class="num">Référence</th>${other?'<th class="num">Ajusté</th>':''}</tr></thead><tbody>${points.slice(-30).map(p=>`<tr><td>${date(p.date)}</td><td class="num">${p.n}</td><td class="num">${p.brier.toFixed(4)}</td><td class="num">${p.reference.toFixed(4)}</td>${other?`<td class="num">${other.find(q=>q.date===p.date)?.brier.toFixed(4)||'—'}</td>`:''}</tr>`).join('')}</tbody></table></div>${points.length>30?'<p class="small">Les 30 dernières dates sont affichées.</p>':''}</details></div>`;
}
function renderHome(){
 const d=current(),h=D.health(d.rows),today=I.localDay(),records=tracked(),done=scoredRecords(records),metrics=E.metrics(done);
 const upcoming=d.rows.filter(m=>!m.score&&!m.conflict&&['UNKNOWN','SCHEDULED','TIMED','IN_PLAY','PAUSED'].includes(m.status)&&(m.kickoff?Date.parse(m.kickoff)>=Date.now()-3*3600000:calendarDay(m)>=today)).sort((a,b)=>(a.kickoff||a.date).localeCompare(b.kickoff||b.date));
 const todayRows=upcoming.filter(m=>calendarDay(m)===today),recent=d.rows.filter(m=>m.score&&!m.conflict&&m.date<=M.today()).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3),waiting=records.filter(r=>recordCategory(r)==='waiting').length;
 const title=todayRows.length?`${todayRows.length} rencontre${todayRows.length>1?'s':''} aujourd’hui`:'Le prochain rendez-vous';
 const next=upcoming[0],line=todayRows.length?names[d.league]+' · '+d.season:next?short(next.home)+' / '+short(next.away)+' · '+when(next):'Aucune rencontre à venir dans cette sélection.';
 $('#content').innerHTML=`<div class="dashboard-hero"><div><div class="eyebrow">${esc(new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'}))}</div><h2>${esc(title)}</h2><p>${esc(line)}</p></div><button data-open-calendar>Voir le calendrier</button></div>
 <div class="dashboard-stats"><div class="stat"><span>À venir dans cette saison</span><strong>${upcoming.length}</strong><small>${todayRows.length} aujourd’hui · ${esc(names[d.league])}</small></div><div class="stat"><span>Résultats renseignés</span><strong>${h.done}<span style="display:inline;font-size:16px"> / ${h.expected}</span></strong><small>${h.missing.length} à vérifier${h.last?' · dernier : '+date(h.last):''}</small></div><div class="stat"><span>Mes prévisions en attente</span><strong>${waiting}</strong><small>${done.length} déjà évaluées dans cette sélection</small></div><div class="stat"><span>Brier de mes prévisions</span><strong>${metrics?metrics.brier.toFixed(3):'—'}</strong><small>${metrics?'Plus bas = mieux · '+metrics.n+' matchs':'Attend un résultat évaluable'}</small></div></div>
 <div class="section-title"><h2>${todayRows.length?'Les matchs du jour':'Les prochaines rencontres'}</h2><button data-open-calendar>Tous les matchs</button></div>${upcoming.length?'<div class="grid home-grid">'+(todayRows.length?todayRows:upcoming).slice(0,4).map(card).join('')+'</div>':empty('Calendrier à consulter.','Choisis la saison en cours pour les prochains matchs, ou consulte les résultats de cette saison.')}
 <div class="section-title"><h2>Derniers résultats connus</h2><button data-open-results>Voir les résultats</button></div>${recent.length?'<div class="recent-results">'+recent.map(m=>`<button class="result-line" data-match="${esc(m.id)}"><span class="small">${date(m.date)}</span><span class="result-team"><span>${esc(short(m.home))}</span><b>${m.score[0]}</b></span><span class="result-team"><span>${esc(short(m.away))}</span><b>${m.score[1]}</b></span></button>`).join('')+'</div>':empty('Aucun résultat renseigné.','Les résultats seront affichés quand les sources les fourniront.')}
 ${chartPanel(done,{id:'homeEvolution'})}<div id="homeAI"></div>`;
 mountAI('homeAI',summaryContext('accueil'));
}
function renderTracking(){
 const allRows=tracked(),rows=scopeRecords(),done=scoredRecords(rows);
 const visible=rows.filter(r=>trackingState==='all'||recordCategory(r)===trackingState);
 const groups=I.byModel(done),modelComparison=groups.length?`<div class="panel"><h2>Bilan par modèle enregistré</h2><div class="tablewrap"><table><thead><tr><th>Modèle</th><th class="num">Matchs</th><th class="num">Brier</th><th class="num">Issue favorite</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${modelLabel({version:g.version})}</td><td class="num">${g.metrics.n}</td><td class="num">${g.metrics.brier.toFixed(4)}</td><td class="num">${pct(g.metrics.accuracy)}</td></tr>`).join('')}</tbody></table></div><p class="small">Ces groupes peuvent contenir des matchs différents. Pour comparer les modèles sur les mêmes matchs, utilise Laboratoire.</p></div>`:'';
 $('#content').innerHTML=`<div class="panel"><div class="row"><h2 style="margin:0 auto 0 0">Prévisions enregistrées</h2><button id="export">Exporter</button><label><span class="small">Importer une sauvegarde</span><input id="import" type="file" accept="application/json,.json"></label></div><p>Les prévisions sont figées sur cet appareil. Les résultats disponibles sont rapprochés à chaque ouverture et actualisation. HTML et Android ont chacun leur stockage ; l’export/import permet de transférer les archives.</p><div class="tracking-filters"><label>Modèle<select id="trackingModel">${[['all','Tous les modèles'],[M.VERSION,'Poisson initial · v1'],[E.VERSION,'Poisson ajusté · v2']].map(([v,t])=>`<option value="${v}" ${v===trackingModel?'selected':''}>${t}</option>`).join('')}</select></label><label>Afficher les prévisions<select id="trackingState">${[['all','Toutes'],['waiting','En attente'],['evaluated','Évaluées'],['excluded','Exclues / non rapprochées']].map(([v,t])=>`<option value="${v}" ${v===trackingState?'selected':''}>${t}</option>`).join('')}</select></label></div><p>${rows.length} prévisions dans cette sélection · ${done.length} résultats évaluables${trackingModel!=='all'?' · filtre par modèle':''}.</p><p class="small">Les graphiques portent sur les résultats évaluables du modèle sélectionné. Le filtre de statut concerne la liste. Horodatage local, sans certification externe.</p></div>
 ${chartPanel(done)}${modelComparison}${report(E.metrics(done))}<div id="trackingAI"></div>
 <div class="section-title"><h2>Mon historique</h2><span class="small">${visible.length} / ${allRows.length}</span></div>${visible.length?visible.slice().sort((a,b)=>b.savedAt.localeCompare(a.savedAt)).slice(0,trackingLimit).map(r=>`<article class="tracking-row"><div><strong>${esc(short(r.match.home))}<br>${esc(short(r.match.away))}</strong><span class="record-date">${date(r.match.date)} · enregistré le ${date(r.savedAt.slice(0,10))}</span><span class="small">${modelLabel(r.pred)}</span></div><div class="record-probs">1 : ${pct(r.pred.probs[0])}<br>N : ${pct(r.pred.probs[1])}<br>2 : ${pct(r.pred.probs[2])}</div><div class="record-result">${r.result?r.result.join(' – '):'—'}</div><button data-record="${esc(r.match.id)}">Voir la prévision</button><div class="record-status">${recordCategory(r)==='evaluated'?'Résultat renseigné':recordCategory(r)==='waiting'?'En attente':'Exclu du bilan'} · ${esc(r.note)}</div></article>`).join('')+(visible.length>trackingLimit?'<button class="loadmore" id="moreTracking">Afficher davantage</button>':''):empty('Aucune prévision dans cette sélection.','Ouvre un match à venir puis enregistre sa prévision avant le coup d’envoi.')}`;
 mountAI('trackingAI',summaryContext('suivi',rows));
}
function recordedDetail(id){
 const f=archive.forecasts.find(r=>r.match.id===id);if(!f)return;
 const currentMatch=D.resolve(f.match,all()),valid=currentMatch&&D.timely(f,currentMatch),result=valid?currentMatch.score:null,p=f.pred,s=archive.snapshots[f.snapshot];
 showDialog('Prévision enregistrée',`<div class="eyebrow">${esc(names[f.match.league])} · ${esc(f.match.season)}</div><h2>${esc(short(f.match.home))}<br><span style="font-weight:400">contre ${esc(short(f.match.away))}</span></h2><p>Enregistrée le ${esc(new Date(f.savedAt).toLocaleString('fr-FR'))}. Match prévu le ${esc(when(f.match))}.</p>${currentMatch&&currentMatch.date!==f.match.date?'<p>Calendrier actuel : '+esc(when(currentMatch))+'.</p>':''}<p>${result?'Résultat renseigné : <b>'+result.join(' – ')+'</b>':!valid?'Résultat exclu : rapprochement ou horaire à vérifier.':currentMatch.conflict?'Résultat exclu : conflit entre sources.':'Résultat en attente.'}</p>${probs(p)}<p class="small">${modelLabel(p)} · probabilités conservées telles qu’enregistrées</p><div class="scoregrid">${p.scores.map(r=>`<div class="scorebox"><strong>${r.h} – ${r.a}</strong><span>${pct(r.p)}</span></div>`).join('')}</div><details><summary>Données de calcul conservées</summary><p>${s.training.length} résultats datés avant le ${date(p.cutoff)}. Dernier résultat utilisé : ${date(p.last)}. Historique des équipes : ${p.homeN} / ${p.awayN} matchs.</p><p class="small">L’export de Mon suivi conserve les données du calcul et son audit.</p></details><div id="detailAI"></div>`);
 mountAI('detailAI',matchContext(f.match,p,f,currentMatch));
}
function dataSource(d){return {id:'donnees',title:d.provider==='football-data'?'Football-data.org et OpenFootball':'OpenFootball',url:d.provider==='football-data'?'https://www.football-data.org/':'https://github.com/openfootball/football.json',detail:'Calendrier et résultats disponibles pour '+names[d.league]+' '+d.season+'. Les sources peuvent être incomplètes ou corrigées.'};}
function qualityFacts(d){const h=D.health(d.rows);return {expected:h.expected,known:h.done,missing:h.missing.length,conflicts:h.conflicts,postponed:h.postponed,lastResult:h.last,consultedAt:d.checkedAt,revision:revision(d.league)};}
function metricFacts(metrics){return metrics?{n:metrics.n,brier:metrics.brier,referenceBrier:metrics.baseline,logloss:metrics.logloss,accuracy:metrics.accuracy}:null;}
function summaryContext(kind,records=tracked()){
 const d=current(),done=scoredRecords(records),comparison=comparisonCache.get(experimentKey(d.league,d.season));
 const sources=[dataSource(d),{id:'suivi',title:'Archives locales Football Lab',detail:'Prévisions enregistrées avant match sur cet appareil ou importées. Probabilités figées ; horodatage déclaratif. Résultats rapprochés des sources actuelles.'}];
 const data={league:names[d.league],season:d.season,asOf:I.localDay(),quality:qualityFacts(d),tracking:{saved:records.length,evaluated:done.length,excluded:records.filter(r=>recordCategory(r)==='excluded').length,metrics:metricFacts(E.metrics(done)),models:I.byModel(done).map(g=>({model:g.version,...metricFacts(g.metrics)}))}};
 if(comparison?.initial){sources.push({id:'comparaison',title:'Laboratoire Football Lab',detail:'Simulation rétrospective sur les mêmes matchs. Les paramètres ajustés sont choisis sur la saison précédente ; seules les dates antérieures servent aux calculs.'});data.comparison={kind:'simulation rétrospective',n:comparison.n,from:comparison.from,to:comparison.to,initial:metricFacts(comparison.initial),adjusted:metricFacts(comparison.adjusted),tuningSeason:comparison.selection.tuningSeason,params:comparison.selection.params||null};}
 return {title:'Bilan '+names[d.league]+' · '+d.season,scope:kind,sources,data};
}
function matchContext(m,p,stored,currentMatch=m){
 const d=datasets.find(d=>d.league===m.league&&d.season===m.season),sources=[dataSource(d)];
 if(p)sources.push({id:'prevision',title:stored?'Prévision enregistrée et audit local':'Calcul statistique Football Lab',detail:stored?'Probabilités figées avec leur historique de calcul. Un résultat publié ensuite n’a pas servi au calcul enregistré.':'Estimation calculée sur les dates antérieures. Pour un match passé, il s’agit d’une simulation rétrospective.'});
 return {title:short(m.home)+' / '+short(m.away),scope:'match',sources,data:{asOf:I.localDay(),league:names[m.league],season:m.season,quality:qualityFacts(d),match:{home:m.home,away:m.away,date:m.date,kickoff:m.kickoff||null,status:m.status,updatedDate:currentMatch?.date||null},forecast:p?{kind:stored?'prévision enregistrée avant match':m.date<M.today()?'simulation rétrospective':'estimation actuelle',savedAt:stored?.savedAt||null,model:p.version||M.VERSION,probs:p.probs,over25:p.over,bothScore:p.btts,topScores:p.scores,goalMeans:[p.lh,p.la],training:{n:p.n,last:p.last,before:p.cutoff,homeN:p.homeN,awayN:p.awayN},params:p.params||E.DEFAULT}:null,result:currentMatch&&!currentMatch.conflict&&(!stored||D.timely(stored,currentMatch))&&currentMatch.date<=M.today()?currentMatch.score:null,unavailable:['blessures','compositions','tirs et xG','cotes','recherche Internet']}};
}
const usd=n=>n.toLocaleString('fr-FR',{style:'currency',currency:'USD',minimumFractionDigits:4,maximumFractionDigits:6});
function safeSource(s){let url='';try{const u=new URL(s.url);if(u.protocol==='https:'&&['github.com','www.football-data.org'].includes(u.hostname))url=u.href}catch{}return url?`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(s.title)}</a>`:esc(s.title);}
function sourceDetails(context){return `<details class="ai-sources"><summary>Données utilisées et sources</summary><ul>${context.sources.map(s=>`<li>${safeSource(s)} · ${esc(s.detail)}</li>`).join('')}</ul><p class="small">${esc(context.title)}${context.data.quality?' · '+context.data.quality.known+'/'+context.data.quality.expected+' résultats attendus renseignés · dernier résultat : '+(context.data.quality.lastResult?date(context.data.quality.lastResult):'inconnu'):''}. L’analyse n’effectue aucune recherche d’actualité sur Internet.</p></details>`;}
function analysisText(record){
 const sources=new Map(record.context.sources.map(s=>[s.id,s]));
 return `<div class="ai-text"><p><b>${esc(record.result.summary)}</b></p><ul>${record.result.observations.map(o=>`<li>${esc(o.text)}<span class="ai-citation">Sources : ${o.sources.map(id=>safeSource(sources.get(id))).join(' · ')}</span></li>`).join('')}</ul>${record.result.limits.length?'<h3>Limites du dossier</h3><ul>'+record.result.limits.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul>':''}</div>`;
}
function analysisMeta(record,cached=false){const u=record.usage;return `<div class="ai-meta"><span>${esc(record.servedModel)}</span><span>${esc(new Date(record.createdAt).toLocaleString('fr-FR'))}</span><span>${u.promptTokens===null?'Tokens d’entrée non communiqués':u.promptTokens+' tokens d’entrée'} · ${u.completionTokens===null?'sortie non communiquée':u.completionTokens+' de sortie'}</span><span>${u.cost===null?'Coût non communiqué par OpenRouter':usd(u.cost)+' · coût communiqué'}</span>${cached?'<span>Relue sans nouvel appel</span>':''}</div>`;}
function paintAI(slot){
 const node=document.getElementById(slot),v=aiViews.get(slot);if(!node||!v)return;
 const s=A.status(),record=v.record,waiting=s.busy&&!record;
 node.innerHTML=`<section class="panel ai-panel"><h2>${v.context.scope==='match'?'Comprendre ce match':'Comprendre ce bilan'}</h2>${record?analysisMeta(record,v.cached)+analysisText(record):'<p class="ai-lead">Une explication des probabilités, des résultats et des données disponibles, avec leurs sources.</p>'}${v.error?'<div class="ai-error" role="status">'+esc(v.error)+'</div>':''}<div class="ai-controls">${record?'<span class="ai-status">Analyse IA enregistrée sur cet appareil.</span>':`<button class="primary" data-analyse="${slot}" ${waiting?'disabled':''}>${waiting?'Analyse en cours…':'Analyser avec l’IA'}</button>`}<button data-configure-ai>${record?'Choisir un autre modèle':'Réglages IA'}</button></div>${!record?`<p class="small">${s.model?esc(s.model.name):'Aucun modèle sélectionné'} · ${s.keyState==='ok'?'clé vérifiée':s.keyState==='checking'?'vérification de la clé en cours':'connexion IA à configurer'}. Un clic transmet ce dossier à OpenRouter. Les probabilités restent celles du calcul statistique.</p>`:''}${sourceDetails(record?.context||v.context)}</section>`;
}
function mountAI(slot,context){
 const v={context,record:null,cached:false,error:''};aiViews.set(slot,v);paintAI(slot);
 A.cached(context).then(record=>{if(aiViews.get(slot)===v){v.record=record;v.cached=record?.cached!==false;paintAI(slot)}}).catch(()=>{});
}
async function runAI(slot){
 const v=aiViews.get(slot);if(!v)return;
 if(A.status().keyState!=='ok'||!A.status().model){aiSettings();return}
 v.error='';
 try{const record=await A.analyse(v.context);if(aiViews.get(slot)===v){v.record=record;v.cached=record?.cached!==false;paintAI(slot)}}catch(e){if(aiViews.get(slot)===v){v.error=e.message;paintAI(slot)}}
}
function aiHistory(id){const r=A.records().find(r=>r.id===id);if(!r)return;showDialog('Analyse IA enregistrée',`<h2>${esc(r.context.title)}</h2>${analysisMeta(r,true)}${analysisText(r)}${sourceDetails(r.context)}<p class="small">Dossier conservé au moment de l’analyse. Les données actuelles peuvent avoir changé depuis.</p>`);}
function keyStatus(){const s=A.status();return s.keyState==='ok'?'Clé vérifiée auprès d’OpenRouter pour cette session.':s.keyState==='checking'?'Vérification de la clé…':s.keyState==='error'?s.keyError:'Aucune clé OpenRouter vérifiée. La clé reste en mémoire pour cette session.';}
function modelOptions(query=''){
 const q=query.trim().toLowerCase(),s=A.status(),list=A.catalog().filter(m=>!q||q==='gratuit'&&m.prompt===0&&m.completion===0||(m.name+' '+m.id).toLowerCase().includes(q));
 const selected=A.catalog().find(m=>m.id===s.model?.id);if(selected&&!list.some(m=>m.id===selected.id))list.unshift(selected);
 return '<option value="">Choisir un modèle</option>'+list.map(m=>`<option value="${esc(m.id)}" ${s.model?.id===m.id?'selected':''}>${esc(m.name)}${m.prompt===0&&m.completion===0?' · 0 $ par token au catalogue':''}</option>`).join('');
}
function balanceLabel(){const s=A.status(),c=s.credits;
 if(s.keyState==='checking')return 'OpenRouter · vérification…';
 if(s.keyState!=='ok')return s.keyState==='error'?'OpenRouter · clé à vérifier':'';
 if(c.state==='error')return 'OpenRouter · crédits à actualiser';
 if(c.state==='checking')return 'OpenRouter · lecture des crédits…';
 if(c.accountBalance!==null)return 'Solde OpenRouter : '+c.accountBalance.toLocaleString('fr-FR',{style:'currency',currency:'USD'});
 if(c.keyRemaining!==null)return 'Budget clé OpenRouter : '+c.keyRemaining.toLocaleString('fr-FR',{style:'currency',currency:'USD'});
 return 'OpenRouter · solde non communiqué';
}
function renderCredits(){
 const label=balanceLabel(),button=$('#accountCredits');button.hidden=!label;button.textContent=label;
 if(!$('#aiCredits'))return;
 const s=A.status(),c=s.credits;let text='Vérifie ta clé pour consulter les crédits.';
 if(s.keyState==='checking'||c.state==='checking')text='Lecture des crédits OpenRouter…';
 else if(s.keyState==='ok'){
  text=c.accountBalance!==null?'Solde du compte : '+usd(c.accountBalance):'Solde du compte non communiqué.';
  if(c.keyRemaining!==null)text+=' Budget restant de cette clé : '+usd(c.keyRemaining)+'.';
  if(c.keyLimit!==null)text+=' Plafond de la clé : '+usd(c.keyLimit)+'.';
  if(c.keyUsage!==null)text+=' Utilisation de la clé : '+usd(c.keyUsage)+'.';
  if(c.at)text+=' Consulté le '+new Date(c.at).toLocaleString('fr-FR')+'.';
  if(c.accountNote)text+=' '+c.accountNote;
  if(c.state==='error')text+=' Dernière actualisation échouée : '+c.error+'. Ces valeurs datent de la dernière consultation réussie.';
 }else if(s.keyState==='error')text='Crédits indisponibles : clé à vérifier.';
 $('#aiCredits').textContent=text;$('#refreshCredits').disabled=s.keyState!=='ok'||c.state==='checking'||s.busy;
}
function updateConnectionSettings(){
 if(dialogMode!=='connections'||!$('#details').open||!$('#fdKeyStatus'))return;
 const s=selection();$('#fdKeyStatus').textContent=connectionState(s.league,s.season).message;
 for(const id of ['useKey','forgetKey','refreshConnections'])$('#'+id).disabled=refreshing;
}
function updateAISettings(){
 renderCredits();
 if(dialogMode!=='connections'||!$('#details').open||!$('#aiKeyStatus'))return;
 const s=A.status();$('#aiKeyStatus').textContent=keyStatus();$('#verifyAIKey').disabled=s.busy||s.keyState==='checking';$('#forgetAIKey').disabled=s.busy||s.keyState==='checking';$('#loadAIModels').disabled=s.loading||s.busy;$('#aiModel').disabled=s.busy;$('#aiMaxTokens').disabled=s.busy;$('#aiDailyCalls').disabled=s.busy;
 $('#aiUsage').textContent=s.calls+'/'+s.dailyCalls+' appels aujourd’hui · '+usd(s.knownCost)+' de coût connu'+(s.unknownCost?' · '+s.unknownCost+' appel(s) au coût non communiqué':'')+'. Les relectures enregistrées ne déclenchent aucun nouvel appel.';
 $('#aiModelInfo').textContent=s.model?s.model.id+' · tarifs des tokens au catalogue : '+usd(s.model.prompt*1000000)+'/million en entrée et '+usd(s.model.completion*1000000)+'/million en sortie.':'Choisis un modèle compatible avec les réponses structurées.';
}
function connectionsPanel(expandAI=false){
 const s=A.status(),records=A.records().slice(-8).reverse();
 showDialog('Connexions et clés',`<div class="ai-form"><p>Tes deux connexions au même endroit. Les clés restent en mémoire pour cette session ; elles ne sont ni sauvegardées ni exportées.</p><p id="connectionNotice" role="status" class="small" hidden></p><div class="connections-grid"><section class="connection-card"><h2>Données football</h2><p class="small">Calendriers et résultats Football-data.org.</p><label for="fdKey">Clé Football-data.org</label><input id="fdKey" type="password" autocomplete="off" spellcheck="false" placeholder="Ta clé football"><div class="row"><button id="useKey" class="primary">Activer la clé</button><button id="forgetKey">Oublier</button></div><p id="fdKeyStatus" role="status"></p><div class="row"><button id="refreshConnections">Actualiser les données</button><button id="viewData">Diagnostic et données</button></div><p class="small">${window.FootballNative?.fetchMatches?'Connexion Android native.':hasRelay?'Version navigateur connectée : relais privé actif. La clé est transmise au relais uniquement pour obtenir les matchs, sans sauvegarde.':'Le fichier HTML et GitHub Pages peuvent être bloqués par Football-data.org. Utilise la version navigateur connectée pour actualiser avec ta clé.'}</p>${!window.FootballNative?.fetchMatches&&!hasRelay?`<a class="web-link" href="${WEB}" target="_blank" rel="noopener">Ouvrir la version navigateur connectée</a><p class="small">Un accès ChatGPT peut être demandé. L’historique de chaque version reste local ; utilise Exporter / Importer pour le transférer.</p>`:''}<p class="small"><a href="https://www.football-data.org/client/register" target="_blank" rel="noopener">Obtenir une clé football</a></p></section><section class="connection-card"><h2>OpenRouter</h2><p class="small">Analyses IA et consultation des crédits.</p><label for="aiKey">Clé OpenRouter</label><input type="password" id="aiKey" autocomplete="off" spellcheck="false" placeholder="Ta clé OpenRouter"><div class="row"><button id="verifyAIKey" class="primary">Activer et vérifier</button><button id="forgetAIKey">Oublier</button></div><p id="aiKeyStatus" role="status"></p><div class="ai-configuration"><p id="aiCredits" role="status"></p><div class="row"><button id="refreshCredits">Actualiser les crédits</button><a href="https://openrouter.ai/settings/credits" target="_blank" rel="noopener">Voir mon compte</a></div></div><p class="small">La vérification et la consultation des crédits ne génèrent aucune analyse. Le solde du compte et le budget de la clé sont affichés selon les informations autorisées par OpenRouter.</p></section></div><details id="aiConfiguration" ${expandAI?'open':''}><summary>Modèle et analyses IA</summary><h2>Une explication à la demande.</h2><p>Le calcul des probabilités et les graphiques restent locaux. L’analyse IA transmet uniquement le dossier du match ou le bilan affiché, quand tu appuies sur son bouton.</p><div class="row"><button id="loadAIModels">${A.catalog().length?'Actualiser le catalogue':'Charger les modèles'}</button><span class="small" id="aiCatalogCount">${A.catalog().length} modèles compatibles${s.catalogAt?' · consulté le '+esc(new Date(s.catalogAt).toLocaleDateString('fr-FR')):''}</span></div><label>Filtrer les modèles<input type="search" id="aiSearch" placeholder="Nom, fournisseur ou « gratuit »"></label><label>Modèle pour l’analyse<select id="aiModel">${modelOptions()}</select></label><p class="small" id="aiModelInfo"></p><details><summary>Consommation et réglages</summary><label>Limite de réponse<select id="aiMaxTokens">${[700,1000,1400].map(n=>`<option value="${n}" ${n===s.maxTokens?'selected':''}>${n} tokens maximum</option>`).join('')}</select></label><label>Nombre maximal d’appels par jour<input type="number" id="aiDailyCalls" min="1" max="50" value="${s.dailyCalls}"></label><p class="small">La limite d’appels est locale et inclut les tentatives échouées. Le plafond de dépenses se règle dans <a href="https://openrouter.ai/settings/keys" target="_blank" rel="noopener">OpenRouter</a>. Les modèles gratuits restent soumis aux quotas du fournisseur.</p></details><div class="ai-configuration"><span id="aiUsage"></span></div><h3>Dernières analyses enregistrées</h3>${records.length?'<ul class="ai-history">'+records.map(r=>`<li><button data-ai-record="${esc(r.id)}">${esc(r.context.title)}<small>${esc(r.servedModel)} · ${esc(new Date(r.createdAt).toLocaleString('fr-FR'))}</small></button></li>`).join('')+'</ul>':'<p class="small">Aucune analyse enregistrée. Configure la clé et le modèle, puis ouvre un match ou un bilan.</p>'}<div class="row"><button id="exportAI" ${!records.length?'disabled':''}>Exporter les analyses</button><button id="clearAI" ${!records.length||s.busy?'disabled':''}>Effacer les analyses</button></div><p class="small">Les analyses sont des interprétations générées à vérifier avec leurs sources. Elles conservent le dossier utilisé, le modèle et la consommation communiquée. Une clé donne accès à un modèle ; elle ne l’entraîne pas sur l’historique.</p></details><div class="ai-error" id="aiSettingsError" role="status" hidden></div></div>`);
 dialogMode='connections';updateConnectionSettings();updateAISettings();
}
function aiSettings(){connectionsPanel(true)}
async function loadAIModels(){
 const error=$('#aiSettingsError');if(error)error.hidden=true;
 try{await A.loadCatalog();if(dialogMode==='connections'&&$('#details').open){$('#aiModel').innerHTML=modelOptions($('#aiSearch').value);$('#aiCatalogCount').textContent=A.catalog().length+' modèles compatibles';$('#loadAIModels').textContent='Actualiser le catalogue';updateAISettings()}}catch(e){if(dialogMode==='connections'&&$('#aiSettingsError')){$('#aiSettingsError').hidden=false;$('#aiSettingsError').textContent=e.message}}
}
async function verifyAIKey(){
 const key=$('#aiKey').value.trim();$('#aiKey').value='';if($('#aiSettingsError'))$('#aiSettingsError').hidden=true;
 try{await A.verify(key);if(!A.catalog().length)await loadAIModels()}catch(e){if(dialogMode==='connections'&&$('#aiSettingsError')){$('#aiSettingsError').hidden=false;$('#aiSettingsError').textContent=e.message}}
}
function openSettings(){
 const s=A.status(),d=current(),h=D.health(d.rows);$('#menuFacts').innerHTML=`${archive.forecasts.length} prévisions enregistrées<br>${h.done}/${h.expected} résultats attendus renseignés<br>IA : ${s.keyState==='ok'?'clé vérifiée pour cette session':'facultative, à configurer'}`;
 $('#settings').showModal();
}
function closeSettings(){if($('#settings').open)$('#settings').close();}
function changeAISettings(settings){try{A.configure(settings);for(const [slot,v] of aiViews)if(document.getElementById(slot))mountAI(slot,v.context)}catch(e){if($('#aiSettingsError')){$('#aiSettingsError').hidden=false;$('#aiSettingsError').textContent=e.message}}}

function labControls(result){
 const allowed=!!result?.selection.available;
 return `<div class="panel lab-intro"><h2>Comparer les modèles.</h2><p>Les réglages sont choisis sur la saison précédente, puis testés sur la saison sélectionnée. Chaque calcul utilise uniquement les résultats de dates antérieures au match. Les réglages restent fixes pendant la saison de test.</p><div class="row"><button id="runComparison" class="primary" ${labBusy?'disabled':''}>${labBusy?'Calcul en cours…':'Comparer les modèles'}</button><span id="labProgress" class="small" role="status">${labBusy?'Calcul sur cet appareil…':'Calcul local, sans tokens.'}</span></div><p class="small">Simulation à partir des résultats actuellement disponibles, parfois incomplets ou corrigés depuis. Elle ne représente pas des prévisions publiées à l’époque.</p></div>
 <div class="panel"><h2>Modèle pour les nouvelles prévisions</h2><div class="segments"><button data-forecast-mode="initial" class="${forecastMode==='initial'?'active':''}" aria-pressed="${forecastMode==='initial'}">Initial · v1</button><button data-forecast-mode="adjusted" ${!allowed?'disabled':''} class="${forecastMode==='adjusted'?'active':''}" aria-pressed="${forecastMode==='adjusted'}">Ajusté · v2</button></div><p class="small">Choix actuel : ${forecastMode==='adjusted'?'modèle ajusté, avec retour au modèle initial si l’historique est insuffisant':'modèle initial'}. ${!allowed?'Lance la comparaison pour vérifier les réglages disponibles. ':''}Les prévisions déjà enregistrées gardent leur modèle et leurs probabilités.</p></div>`;
}
function comparisonReport(result){
 const r=result,t=r.selection;
 const selectionInfo=t.available?`<p>Réglages choisis sur <b>${esc(t.tuningSeason)}</b> : ${t.n} matchs de validation du ${date(t.validationFrom)} au ${date(t.validationTo)}. Aucun résultat de ${esc(r.season)} ne sert à choisir ces réglages.</p><p>Demi-vie : <b>${t.params.halfLife} jours</b> · Lissage : <b>${t.params.prior} matchs</b>.</p><details><summary>Réglages testés (${t.candidates.length})</summary><p>Après une demi-vie, un résultat compte moitié moins. Le lissage rapproche les forces d’une équipe de la moyenne du championnat quand elle a peu d’historique. Le réglage retenu minimise le Brier de validation.</p><div class="tablewrap"><table><thead><tr><th>Demi-vie</th><th>Lissage</th><th>Brier validation</th></tr></thead><tbody>${t.candidates.map(c=>`<tr><td>${c.halfLife} j</td><td>${c.prior}</td><td>${c.brier.toFixed(4)}${c.halfLife===t.params.halfLife&&c.prior===t.params.prior?' · retenu':''}</td></tr>`).join('')}</tbody></table></div></details>`:`<p>${esc(t.reason)}. Le modèle initial reste disponible.</p>`;
 const intro=`<div class="panel"><h2>Réglages · ${esc(names[r.league])}</h2>${selectionInfo}<p class="small">Limite de sélection : avant le ${date(t.before)}. Les forces des équipes sont ensuite recalculées avant chaque match avec les scores antérieurs disponibles ; les deux réglages ne changent pas pendant le test.</p></div>`;
 if(!r.initial)return intro+empty('Aucun résultat de test évaluable.','Les réglages peuvent être examinés ; le bilan attend des matchs avec un score final et un historique suffisant.');
 const table=`<div class="panel"><h2>Résultats du test · ${esc(r.season)}</h2><p>${r.n} matchs du ${date(r.from)} au ${date(r.to)} · ${r.skipped} exclus faute d’historique.${r.n<100?' Échantillon encore limité.':''}</p><div class="tablewrap"><table id="comparisonTable"><thead><tr><th>Modèle</th><th>Brier ↓</th><th>Perte log. ↓</th><th>Issue favorite ↑</th></tr></thead><tbody>${[['Initial · v1',r.initial],['Ajusté · v2',r.adjusted]].filter(x=>x[1]).map(([label,m])=>`<tr><td>${label}</td><td>${m.brier.toFixed(4)}</td><td>${m.logloss.toFixed(4)}</td><td>${pct(m.accuracy)}</td></tr>`).join('')}</tbody></table></div><p class="small">${r.adjusted?"Les deux modèles sont évalués sur les mêmes matchs.":"Seul le modèle initial peut être évalué avec cet historique."} La référence de fréquences historiques utilise la pondération du modèle initial.</p>${r.adjusted?`<p class="${r.delta<0?'positive':r.delta>0?'negative':''}">${Math.abs(r.delta)<1e-12?'Les deux modèles sont équivalents sur ce test.':r.delta<0?'Le modèle ajusté obtient un Brier plus bas sur ce test.':'Le modèle ajusté obtient un Brier plus élevé sur ce test.'} Écart ajusté − initial : ${r.delta.toFixed(4)}. Ce bilan reste descriptif.</p><div class="segments" aria-label="Modèle à examiner"><button data-lab-inspect="initial" class="${labInspect==='initial'?'active':''}">Examiner l’initial</button><button data-lab-inspect="adjusted" class="${labInspect==='adjusted'?'active':''}">Examiner l’ajusté</button></div>`:''}</div>`;
 return intro+table+chartPanel(r.initialRows,{id:'labEvolution',title:'Évolution du test historique',label:'Initial · v1',adjusted:r.adjusted?r.adjustedRows:null})+report(labInspect==='adjusted'&&r.adjusted?r.adjusted:r.initial);
}
function renderLab(){
 const s=selection(),key=experimentKey(s.league,s.season),result=comparisonCache.get(key);
 if(result){$('#content').innerHTML=labControls(result)+comparisonReport(result)+'<div id="labAI"></div>';mountAI('labAI',summaryContext('laboratoire'));return;}
 const baseline=baselineCache.get(key)||remember(baselineCache,key,M.backtest(all(),s.league,s.season));
 $('#content').innerHTML=labControls(null)+`<div class="panel"><h2>Modèle initial · bilan chronologique</h2><p>Poisson lissé v1, demi-vie 180 jours et lissage 8 matchs. ${baseline.skipped} matchs exclus faute d’historique. Un score manquant reste inconnu.</p></div>`+chartPanel(baseline.rows,{id:'labEvolution',title:'Évolution du test historique',label:'Initial · v1'})+report(E.metrics(baseline.rows));
}
async function runComparison(){
 if(labBusy)return;const s=selection(),asOf=M.today(),key=experimentKey(s.league,s.season),rows=all();labBusy={key};renderLab();
 try{const result=await E.compareAsync(rows,s.league,s.season,asOf,progress=>{
  if(tab==='lab'&&experimentKey($('#league').value,$('#season').value)===key&&$('#labProgress'))$('#labProgress').textContent=progress.phase==='tuning'?`Réglages : ${progress.done}/${progress.total}`:`Test : ${progress.done}/${progress.total} matchs`;
 });
 if(experimentKey(s.league,s.season)!==key)throw Error('Les données ont changé pendant le calcul. Relance la comparaison.');
 remember(comparisonCache,key,result);remember(tuningCache,tuningKey(s.league,s.season,asOf),result.selection);
 }catch(e){say('Comparaison interrompue : '+safeError(e))}finally{labBusy=null;if(tab==='lab')renderLab()}
}
function setForecastMode(mode){
 if(!['initial','adjusted'].includes(mode))return;
 if(mode==='adjusted'){const s=selection(),result=comparisonCache.get(experimentKey(s.league,s.season));if(!result?.selection.available){say('Lance la comparaison pour vérifier l’historique du modèle ajusté.');return}}
 forecastMode=mode;try{localStorage.setItem('football-lab-model',mode)}catch{say('Choix utilisé pour cette session ; stockage indisponible.')}
 render();
}
function render(){
 health();renderConnection();$('#modelTag').textContent=forecastMode==='adjusted'?'Mode ajusté · v2':'Mode initial · v1';$('#savedCount').textContent=archive.forecasts.length;
 $('#searchWrap').hidden=tab!=='matches';$('#calendarFilters').hidden=tab!=='matches';
 const titles={home:['Ton tableau de bord.','Matchs, prévisions et résultats, au même endroit.'],matches:['Le terrain d’observation.','Des prévisions explicables. Des résultats pour les éprouver.'],table:['Les forces en présence.','Un classement reconstitué à partir des scores disponibles.'],tracking:['Confronter les prévisions.','Ce qui a été enregistré, puis ce qui s’est passé.'],lab:['Mettre le modèle à l’épreuve.','Un test chronologique, comparé à une référence simple.']};
 $('#heading').textContent=titles[tab][0];$('#subtitle').textContent=titles[tab][1];document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);if(b.closest('nav'))b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')});
 ({home:renderHome,matches:renderMatches,table:renderTable,tracking:renderTracking,lab:renderLab}[tab])();
}
function showDialog(title,body){closeSettings();dialogMode='';$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;if(!$('#details').open)$('#details').showModal()}
function detail(id){const m=all().find(x=>x.id===id);if(!m)return;selected=m;const stored=existing(m),p=stored?.pred||prediction(m),historical=m.date<M.today();const params=p?.version===E.VERSION?p.params:E.DEFAULT;showDialog('Analyse du match',`<div class="eyebrow">${esc(names[m.league])} · ${esc(when(m))}</div><h2>${esc(short(m.home))}<br><span style="font-weight:400;color:var(--muted)">contre ${esc(short(m.away))}</span></h2><p class="small">${esc(D.labels[m.status])} · ${m.provider==='football-data'?'Football-data.org':'OpenFootball'}${m.providerId?' · match '+m.providerId:''}${m.scheduleChange?' · calendrier modifié':''}</p>${m.conflict?'<p>Conflit de sources : ce résultat est exclu des calculs jusqu’à résolution.</p>':''}${m.score?`<p>Résultat renseigné : <b>${m.score.join(' – ')}</b></p>`:''}${p?`${probs(p)}<p class="small">${modelLabel(p)}${p.version===E.VERSION?" · réglages choisis sur "+esc(p.selection.tuningSeason):" · réglages fixes"}</p><h3>Scores les plus probables</h3><div class="scoregrid">${p.scores.map(s=>`<div class="scorebox"><strong>${s.h} – ${s.a}</strong><span>${pct(s.p)}</span></div>`).join('')}</div><h3>Autres probabilités · 90 minutes</h3><div class="detailstats"><div>Plus de 2,5 buts<strong>${pct(p.over)}</strong></div><div>Moins de 2,5 buts<strong>${pct(1-p.over)}</strong></div><div>Les deux équipes marquent<strong>${pct(p.btts)}</strong></div><div>Au moins une équipe ne marque pas<strong>${pct(1-p.btts)}</strong></div></div><p class="small">${historical&&!stored?'Simulation rétrospective avec les données actuelles. ':''}Buts moyens du modèle : ${p.lh.toFixed(2)} / ${p.la.toFixed(2)}. Ces moyennes ne sont pas des xG issus des tirs.</p><details><summary>Comprendre ce calcul</summary><p>${p.n} matchs d’entraînement, tous datés avant le ${date(p.cutoff)}. Dernier résultat utilisé : ${date(p.last)}. Historique disponible : ${p.homeN} matchs pour le domicile, ${p.awayN} pour l’extérieur.</p><p>Les buts marqués et encaissés à domicile/extérieur sont pondérés par leur ancienneté. Demi-vie : ${params.halfLife} jours. Lissage : ${params.prior} matchs équivalents à la moyenne du championnat. Les moyennes de buts sont bornées entre 0,15 et 5. Pas de données sur les blessures, compositions, tirs ou absences.</p><p>Les buts des deux équipes sont supposés indépendants. La grille des scores couvre 0 à 24 buts par équipe et est normalisée. Ces modèles n’intègrent pas de correction Dixon–Coles. ${p.version===E.VERSION?"La demi-vie et le lissage ont été choisis sur "+esc(p.selection.tuningSeason)+", avant le "+date(p.selection.before)+", sur "+p.selection.n+" matchs de validation. Ils ne sont pas choisis sur les résultats de cette saison.":"Le modèle initial conserve les réglages fixes de la première version."}</p></details><p class="small">Les horaires confirmés sont convertis dans le fuseau de cet appareil. Sans horaire confirmé, l’enregistrement ferme avant le jour du match (UTC). Avec un horaire confirmé, il ferme au coup d’envoi.</p>${stored?'<p class="badge">Prévision déjà enregistrée, elle ne sera pas remplacée.</p>':D.eligible(m)?'<button class="primary" id="saveForecast">Enregistrer cette prévision</button>':'<p class="small">Enregistrement fermé pour ce match. Les simulations restent consultables.</p>'}`:'<p>Analyse indisponible : historique insuffisant, conflit de données ou statut du match ne permettant pas une prévision avant match.</p>'}`);
 const slot=document.createElement('div');slot.id='detailAI';$('#dialogBody').append(slot);mountAI('detailAI',matchContext(m,p,stored));
}
async function saveForecast(){const m=selected&&D.resolve(selected,all());if(!m||!D.eligible(m))return;const p=prediction(m);if(!p||!!existing(m))return;const b=$('#saveForecast');b.disabled=true;
 try{const training=all().filter(x=>x.league===m.league&&x.score&&x.date<p.cutoff&&M.day(p.cutoff)-M.day(x.date)<=1096).map(x=>[x.date,x.home,x.away,...x.score]);const model=p.version===E.VERSION?{version:p.version,params:p.params,selection:p.selection}:undefined,tuningInputs=model?E.tuningInputs(all(),p.selection):undefined;const payload=JSON.stringify({league:m.league,cutoff:p.cutoff,training,revision:revision(m.league),model,tuningInputs});const hash=await digest(payload);const snapshot=hash;if(!D.eligible(m)||revision(m.league)!==JSON.parse(payload).revision)throw Error('Données modifiées');const next=JSON.parse(JSON.stringify(archive));next.snapshots[snapshot]={league:m.league,cutoff:p.cutoff,training,revision:revision(m.league),...(model?{model,tuningInputs}:{})};next.forecasts.push({match:m,pred:p,savedAt:new Date().toISOString(),snapshot});localStorage.setItem('football-lab-archive',JSON.stringify(next));archive=next;detail(m.id);render();say('Prévision enregistrée sur cet appareil, avec ses données de calcul.');}catch{b.disabled=false;say('Enregistrement impossible : stockage indisponible ou plein. Aucune prévision ajoutée.');}}
async function digest(s){if(!globalThis.crypto?.subtle)throw Error('Un navigateur récent avec un contexte sécurisé est nécessaire');const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return Array.from(new Uint8Array(bytes),x=>x.toString(16).padStart(2,'0')).join('')}
function saveData(){localStorage.setItem('football-lab-data-v11',JSON.stringify(datasets.map(({rows,issues,...d})=>d)));localStorage.setItem('football-lab-source-log',JSON.stringify(sourceLog.slice(-60)));}
async function getJSON(url,headers={},options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(url,{...options,signal:controller.signal,cache:'no-store',credentials:options.credentials||'omit',redirect:'error',headers});if(!r.ok)throw Error(r.status===401?'HTTP 401 : clé refusée':r.status===403?'HTTP 403 : accès non inclus ou clé refusée':r.status===429?'HTTP 429 : quota temporairement atteint':'HTTP '+r.status);const text=await r.text();if(text.length>2000000)throw Error('Fichier trop volumineux');return JSON.parse(text)}finally{clearTimeout(timer)}}
const nativeCalls=new Map();let nativeSeq=0;
window.footballApiResult=(id,result)=>{const cb=nativeCalls.get(id);if(cb){nativeCalls.delete(id);cb(result)}};
function apiFetch(league,season,key){if(window.FootballNative?.fetchMatches)return new Promise((resolve,reject)=>{const id=++nativeSeq,t=setTimeout(()=>{nativeCalls.delete(id);reject(Error('Délai dépassé'))},20000);nativeCalls.set(id,r=>{clearTimeout(t);r.ok?resolve(r.data):reject(Error(r.error||'Connexion impossible'))});try{FootballNative.fetchMatches(id,D.codes[league],Number(season.slice(0,4)),key)}catch{clearTimeout(t);nativeCalls.delete(id);reject(Error('Connexion Android indisponible'))}});if(hasRelay)return getJSON('/api/football',{'Content-Type':'application/json'},{method:'POST',credentials:'same-origin',body:JSON.stringify({competition:D.codes[league],year:Number(season.slice(0,4)),key})});return getJSON(`https://api.football-data.org/v4/competitions/${D.codes[league]}/matches?season=${season.slice(0,4)}`,{'X-Auth-Token':key}).catch(e=>{if(e.name==='TypeError')throw Error('Connexion impossible depuis ce navigateur : réseau ou accès bloqué (CORS). Ouvre la version navigateur connectée depuis Connexions et clés');if(e.name==='AbortError')throw Error('Délai de connexion dépassé');throw e});}
async function refresh(){if(refreshing)return;if(Date.now()-refreshAttempt<60000){say('Attends une minute entre deux actualisations pour respecter les quotas.');return;}refreshAttempt=Date.now();refreshing=true;$('#refresh').disabled=true;$('#refresh').textContent='Actualisation…';say('Lecture des sources…');let openCount=0,apiCount=0;const failures=[],season=$('#season').value,keyUsed=apiKey;
 refreshErrors=[];if(keyUsed)for(const league of Object.keys(names))apiChecks.set(checkId(league,season),{state:'loading'});renderConnection();
 for(const league of Object.keys(names)){const i=datasets.findIndex(d=>d.league===league&&d.season===season),old=datasets[i];if(!old)continue;let candidate={...old},changed=false;const now=new Date().toISOString();
 try{const data=await getJSON(`https://raw.githubusercontent.com/openfootball/football.json/master/${season}/${league}.1.json`);candidate=dataset({...candidate,data,revision:await digest(JSON.stringify(data)),checkedAt:now,openCheckedAt:now},old.rows);changed=true;openCount++;}catch(e){failures.push(names[league]+' / OpenFootball : '+safeError(e,keyUsed))}
 if(keyUsed){let stage='request';try{const raw=await apiFetch(league,season,keyUsed);stage='parse';const parsed=D.footballData(raw,league,season,REG);candidate=dataset({...candidate,fdOmitted:(candidate.fdData?.matches||[]).filter(x=>!raw.matches.some(y=>y.id===x.id)).map(x=>x.id),fdData:combineFD(candidate.fdData,raw),fdCheckedAt:now,checkedAt:now,revision:await digest(JSON.stringify({open:candidate.data,fd:raw}))},old.rows);changed=true;apiCount++;apiChecks.set(checkId(league,season),{state:'ok',received:raw.matches.length,finals:parsed.rows.filter(m=>m.score).length,ignored:parsed.ignored.length});}catch(e){const error=safeError(e,keyUsed);apiChecks.set(checkId(league,season),{state:'error',stage,error});failures.push(names[league]+' / Football-data.org : '+error)}}
 if(changed){candidate.revision=await digest(JSON.stringify({open:candidate.data,fd:candidate.fdData}));datasets[i]=candidate;sourceLog.push({at:now,league,season,provider:candidate.provider,issues:candidate.issues.length,expected:D.health(candidate.rows).expected,known:D.health(candidate.rows).done});}renderConnection();}
 try{saveData()}catch{failures.push('Stockage indisponible : mise à jour non conservée')}
 refreshing=false;$('#refresh').disabled=false;$('#refresh').textContent='Actualiser';render();say(`OpenFootball : ${openCount}/3 championnats relus. Football-data.org : ${keyUsed?apiCount+'/3 réponses intégrées.':'non consulté, aucune clé active.'} `+(failures.length?'Consulte Diagnostic pour le détail des erreurs.':'Les données reçues peuvent rester incomplètes.'));refreshErrors=failures;}
function exportJSON(value,name){const text=JSON.stringify(value,null,2);if(window.FootballNative?.exportNamed){FootballNative.exportNamed(text,name);return}if(window.FootballNative?.exportJson){FootballNative.exportJson(text);return}const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function sourcePanel(){const d=current(),h=D.health(d.rows);showDialog('Données & calendrier',apiDiagnostics(d)+`<h2>Des sources identifiées.</h2><p>OpenFootball reste disponible sans inscription. Football-data.org propose une clé personnelle gratuite pour les trois championnats. Sans cette clé, la fraîcheur des données reste celle d’OpenFootball.</p><p><a href="https://www.football-data.org/client/register" target="_blank" rel="noopener">Créer une clé gratuite sur Football-data.org</a></p><div class="row"><button id="openConnections">Connexions et clés</button>${!window.FootballNative?.fetchMatches&&!hasRelay?`<a class="web-link" href="${WEB}" target="_blank" rel="noopener">Version navigateur connectée</a>`:''}</div><p>Football data provided by the Football-Data.org API. Les horaires confirmés sont affichés en ${esc(tz)}. Les données gratuites ne sont pas du direct.</p><h3>${esc(names[d.league])} · ${esc(d.season)}</h3><p>${h.done}/${h.expected} résultats attendus renseignés · ${h.conflicts} conflits · ${h.postponed} reports/suspensions.</p><p class="small">OpenFootball consulté : ${esc(new Date(d.openCheckedAt).toLocaleString('fr-FR'))}${d.fdCheckedAt?' · Données Football-data.org reçues : '+esc(new Date(d.fdCheckedAt).toLocaleString('fr-FR')):''}. L’heure de consultation ne prouve pas que les résultats sont récents.</p><details><summary>Contrôles et anomalies (${d.issues.length})</summary><ul>${d.issues.slice(0,30).map(x=>`<li>${esc(x.reason)}${x.home?' : '+esc(x.home)+' / '+esc(x.away):''}</li>`).join('')||'<li>Aucune anomalie de rapprochement détectée.</li>'}</ul><p>Les scores contradictoires sont exclus. Les rencontres reportées ne sont pas comptées comme résultats manquants. Les correspondances inconnues sont ignorées, sans rapprochement approximatif.</p></details><h3>Transférer les données</h3><div class="row"><button id="exportData">Exporter les données</button><label>Importer un fichier de données<input id="importData" type="file" accept="application/json,.json"></label></div><p class="small">Format Football Lab 1.1, ou réponse « matches » de Football-data.org pour le championnat et la saison sélectionnés. Les prévisions déjà enregistrées restent intactes.</p><details><summary>Dernières actualisations</summary><ul>${sourceLog.slice(-9).reverse().map(x=>`<li>${esc(x.at)} · ${esc(names[x.league]||x.league)} · ${esc(x.known)}/${esc(x.expected)} résultats</li>`).join('')||'<li>Aucune actualisation dans cette version.</li>'}</ul></details>`);}
async function importData(file){if(!file)return;try{if(file.size>15000000)throw Error('Fichier trop volumineux');const raw=JSON.parse(await file.text());let entries;if(raw.format==='football-lab-data-1.1'){if(!Array.isArray(raw.datasets)||raw.datasets.length>20)throw Error('Format invalide');entries=raw.datasets;}else{const s=selection(),old=current();entries=[{...old,fdData:raw,fdCheckedAt:new Date().toISOString()}]}
 const next=datasets.slice();for(const e of entries){const i=next.findIndex(d=>d.league===e.league&&d.season===e.season);if(i<0)throw Error('Saison ou championnat non pris en charge');if(e.fdData)D.footballData(e.fdData,e.league,e.season,REG);const clean={league:e.league,season:e.season,data:e.data,openCheckedAt:e.openCheckedAt||e.checkedAt||bundle.fetchedAt,fdData:e.fdData?combineFD(next[i].fdData,e.fdData):next[i].fdData,fdOmitted:(next[i].fdData?.matches||[]).filter(x=>!e.fdData?.matches.some(y=>y.id===x.id)).map(x=>x.id),checkedAt:e.checkedAt||new Date().toISOString(),fdCheckedAt:e.fdCheckedAt,revision:await digest(JSON.stringify({open:e.data,fd:e.fdData}))};next[i]=dataset(clean,next[i].rows);}
 localStorage.setItem('football-lab-data-v11',JSON.stringify(next.map(({rows,issues,...d})=>d)));datasets=next;$('#details').close();render();say('Données importées et contrôlées. Les prévisions enregistrées sont conservées.');}catch(e){say('Import de données impossible : '+e.message)}}
function download(){const text=JSON.stringify({...archive,exportedAt:new Date().toISOString()},null,2),name='football-lab-suivi-'+M.today()+'.json';if(window.FootballNative?.exportNamed){FootballNative.exportNamed(text,name);return}if(window.FootballNative?.exportJson){FootballNative.exportJson(text);return}const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importFile(file){if(!file)return;try{if(file.size>15000000)throw Error('Fichier trop volumineux');const incoming=validateArchive(JSON.parse(await file.text())),next=JSON.parse(JSON.stringify(archive));let n=0;for(const f of incoming.forecasts){if(next.forecasts.some(x=>D.key(x.match)===D.key(f.match)))continue;next.forecasts.push(f);next.snapshots[f.snapshot]=incoming.snapshots[f.snapshot];n++}localStorage.setItem('football-lab-archive',JSON.stringify(next));archive=next;render();say(`${n} prévisions importées. Les prévisions existantes sont conservées.`)}catch(e){say('Import impossible : '+e.message)}}
function method(){showDialog('Sources & méthode',`<div class="eyebrow">UNE EXPÉRIENCE REPRODUCTIBLE</div><h2>Du résultat à la probabilité.</h2><p>Football Lab 1.3.1 conserve les modèles statistiques de la version 1.2. Le calcul des probabilités et les graphiques s’effectuent sur ton appareil, sans tokens. L’analyse IA facultative utilise OpenRouter seulement à ta demande.</p><h3>Données</h3><p><a href="https://github.com/openfootball/football.json" target="_blank" rel="noopener">OpenFootball / football.json</a> : calendriers et résultats déclarés dans le domaine public. Instantané intégré récupéré le ${date(bundle.fetchedAt.slice(0,10))}, révision ${esc(bundle.sha.slice(0,12))}. Saisons 2023–2024 à 2026–2027. Le bouton Actualiser relit la saison sélectionnée. La connexion facultative Football-data.org complète les données, si une clé gratuite est renseignée. Les deux sources restent identifiées et les désaccords sont exclus des calculs.</p><p>Les sources communautaires peuvent être incomplètes, corrigées ou en retard. Un score absent reste inconnu. Les noms d’équipes sont rapprochés par normalisation contrôlée, sans correspondance approximative. Les noms inconnus sont signalés. Les mises à jour ne remplacent jamais les probabilités déjà enregistrées.</p><h3>Modèle</h3><p>Forces offensives et défensives calculées séparément à domicile et à l’extérieur ; historique limité aux 3 dernières années, pondération exponentielle de demi-vie 180 jours, lissage de 8 matchs équivalents. Les forces relatives sont multipliées par la moyenne des buts du championnat, puis transformées en probabilités par deux lois de Poisson indépendantes.</p><p>Aucun ajustement Dixon–Coles, aucune blessure ou composition intégrée. Ce modèle de départ est volontairement simple et peut faire moins bien que la référence. Il ne calcule aucune mise ni aucun ticket.</p><h3>Comparaison 1.2</h3><p>Le modèle initial garde ses réglages. Le modèle ajusté teste neuf combinaisons : demi-vies de 90, 180 et 365 jours, lissages de 4, 8 et 16 matchs. Le plus petit Brier sur la saison précédente choisit les réglages par championnat, avec au moins 120 matchs de validation et 60 matchs antérieurs pour calculer chaque prévision. La saison sélectionnée sert au test des deux modèles, sur les mêmes matchs. Les réglages restent fixes ; les forces des équipes utilisent les scores antérieurs au fil du test. La référence commune utilise les fréquences pondérées comme le modèle initial.</p><p>Dans Laboratoire, lance la comparaison puis choisis le modèle pour les nouvelles prévisions. Un historique insuffisant conserve le modèle initial. Les prévisions et audits anciens restent inchangés. Les nouveaux audits du modèle ajusté contiennent aussi ses réglages et les résultats ayant servi à les choisir.</p><h3>Évaluation</h3><p>Le laboratoire recalcule chaque match avec les seules dates antérieures, en excluant tous les matchs du même jour. Les résultats historiques disponibles aujourd’hui peuvent avoir été corrigés depuis : ces simulations ne remplacent pas le suivi prospectif.</p><p>Le score de Brier et la perte logarithmique mesurent la qualité des probabilités. Les graphiques de calibration couvrent domicile, nul et extérieur. Ils comparent les probabilités aux fréquences observées, sans correction automatique. Les matchs sans résultat sont exclus et restent signalés.</p><h3>Dashboard et analyse IA 1.3</h3><p>Accueil montre les prochains matchs et les derniers résultats effectivement renseignés. Mon suivi rapproche les résultats disponibles des prévisions conservées, puis affiche une courbe de Brier cumulé et un bilan par modèle. Des groupes de matchs différents ne prouvent pas la supériorité d’un modèle.</p><p>L’analyse OpenRouter reçoit un dossier compact avec sources, probabilités et qualité des données. Elle ne change ni les modèles statistiques ni les prévisions enregistrées, et ne recherche pas d’actualité sur Internet. Les réponses sont conservées sur cet appareil par dossier et modèle ; les relire n’envoie aucun nouvel appel. Le catalogue, la clé, les formats et les sources cités sont contrôlés. Le texte produit reste une interprétation à vérifier.</p><p>La clé IA reste en mémoire pour la session. Les analyses exportées contiennent le dossier utilisé, les modèles et les tokens/coûts communiqués, jamais la clé. La limite locale d’appels inclut les tentatives échouées ; aucun nouvel appel automatique n’est effectué après un échec. Le plafond financier se définit auprès d’OpenRouter.</p><h3>Ton suivi</h3><p>Chaque prévision est enregistrée avant le coup d’envoi confirmé, ou avant le jour du match si l’heure est inconnue, avec ses données de calcul. L’horloge est celle de l’appareil : ce n’est pas une certification indépendante. Le suivi utilise le championnat, la saison et les équipes domicile/extérieur pour résister aux reports, ainsi que les identifiants du fournisseur lorsqu’ils sont disponibles. Les ambiguïtés restent non résolues ; aucun résultat n’est deviné.</p><p>Le stockage est local. L’export JSON conserve les données nécessaires pour reproduire le calcul. Un effacement des données du navigateur ou une désinstallation peut supprimer le suivi.</p>`)}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.calibration!==undefined){calibrationOutcome=Number(b.dataset.calibration);if(tab==='lab')renderLab();else if(tab==='tracking')renderTracking();return}
 if(b.dataset.labInspect){labInspect=b.dataset.labInspect;renderLab();return}
 if(b.id==='runComparison'){runComparison();return}
 if(b.dataset.forecastMode){setForecastMode(b.dataset.forecastMode);return}
 if(b.dataset.tab){closeSettings();tab=b.dataset.tab;render();return}
 if(b.hasAttribute('data-open-calendar')||b.hasAttribute('data-open-results')){tab='matches';mode=b.hasAttribute('data-open-results')?'results':'upcoming';limit=24;$('#search').value='';$('#fromDate').value='';$('#toDate').value='';render();return}
 if(b.dataset.mode){mode=b.dataset.mode;limit=24;render();return}
 if(b.dataset.match){detail(b.dataset.match);return}
 if(b.dataset.record){recordedDetail(b.dataset.record);return}
 if(b.dataset.analyse){runAI(b.dataset.analyse);return}
 if(b.hasAttribute('data-configure-ai')||b.id==='aiSettings'){aiSettings();return}
 if(b.dataset.aiRecord){aiHistory(b.dataset.aiRecord);return}
 if(b.id==='menuToggle'){openSettings();return}
 if(b.id==='closeSettings'){closeSettings();return}
 if(b.id==='menuMethod'){method();return}
 if(b.id==='connectionDetails'||b.id==='viewData'){sourcePanel();return}
 if(b.id==='openConnections'||b.id==='accountCredits'){connectionsPanel();return}
 if(b.id==='refreshConnections'){refresh();return}
 if(b.id==='refreshCredits'){A.refreshCredits().catch(e=>say(e.message));return}
 if(b.id==='more'){limit+=24;renderMatches();return}
 if(b.id==='moreTracking'){trackingLimit+=30;renderTracking();return}
 if(b.id==='saveForecast'){saveForecast();return}
 if(b.id==='export'){download();return}
 if(b.id==='exportData'){exportJSON({format:'football-lab-data-1.1',datasets:datasets.map(({rows,issues,...d})=>d)},'football-lab-donnees.json');return}
 if(b.id==='loadAIModels'){loadAIModels();return}
 if(b.id==='verifyAIKey'){verifyAIKey();return}
 if(b.id==='forgetAIKey'){try{A.forget();$('#aiKey').value='';updateAISettings()}catch(e){$('#aiSettingsError').hidden=false;$('#aiSettingsError').textContent=e.message}return}
 if(b.id==='exportAI'){exportJSON(A.export(),'football-lab-analyses-'+M.today()+'.json');return}
 if(b.id==='clearAI'){try{A.clearRecords();aiViews.clear();aiSettings();render()}catch(e){$('#aiSettingsError').hidden=false;$('#aiSettingsError').textContent=e.message}return}
 if(b.id==='useKey'){
  if(refreshing){say('Attends la fin de l’actualisation pour changer la clé.');return}
  const k=$('#fdKey').value.trim();if(!/^[A-Za-z0-9_-]{10,128}$/.test(k)){say('Format de clé non valide.');return}
  apiKey=k;apiChecks.clear();refreshErrors=[];$('#fdKey').value='';renderConnection();say('Clé saisie pour cette session. Elle sera vérifiée lors de l’actualisation.');return
 }
 if(b.id==='forgetKey'){
  if(refreshing){say('Attends la fin de l’actualisation pour changer la clé.');return}
  apiKey='';apiChecks.clear();refreshErrors=[];if($('#fdKey'))$('#fdKey').value='';renderConnection();say('Clé oubliée.');
 }
});
$('#sources').onclick=()=>connectionsPanel();
$('#fromDate').onchange=$('#toDate').onchange=()=>{limit=24;renderMatches()};
$('#refresh').onclick=refresh;$('#method').onclick=method;
$('#closeDialog').onclick=()=>$('#details').close();
$('#details').addEventListener('click',e=>{if(e.target===$('#details'))$('#details').close()});
$('#settings').addEventListener('click',e=>{if(e.target===$('#settings'))closeSettings()});
$('#league').onchange=()=>{limit=24;trackingLimit=30;render()};
$('#season').onchange=()=>{limit=24;trackingLimit=30;mode=$('#season').value!==CURRENT?'results':'upcoming';render()};
$('#search').oninput=()=>{limit=24;renderMatches()};
