document.addEventListener('change',e=>{
 if(e.target.id==='import')importFile(e.target.files[0]);
 if(e.target.id==='importData')importData(e.target.files[0]);
 if(e.target.id==='trackingModel'){trackingModel=e.target.value;trackingLimit=30;renderTracking()}
 if(e.target.id==='trackingState'){trackingState=e.target.value;trackingLimit=30;renderTracking()}
 if(e.target.id==='aiModel')changeAISettings({model:e.target.value});
 if(e.target.id==='aiMaxTokens')changeAISettings({maxTokens:Number(e.target.value)});
 if(e.target.id==='aiDailyCalls')changeAISettings({dailyCalls:Number(e.target.value)});
});
